import java.util.Scanner;

public class Main {
    public static long gcdOf(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static class Fraction {
        long numerator, denominator;

        Fraction() {
            this.numerator = 0;
            this.denominator = 1;
        }

        Fraction(long n, long d) {
            this.numerator = n;
            this.denominator = d;
        }

        void reduceFraction() {
            long g = gcdOf(numerator, denominator);
            numerator /= g;
            denominator /= g;
        }

        boolean isLess(Fraction other) {
            return numerator * other.denominator < other.numerator * denominator;
        }

        void display() {
            System.out.print(numerator + "/" + denominator);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long total = sc.nextLong();

        Fraction limit = new Fraction(50, 1);
        Fraction base = new Fraction(x, y);
        long min_r = 0, min_i = 1;

        for (long i = 1; i <= total; ++i) {
            long r = (base.numerator * i) / base.denominator;
            long z = (base.numerator * i) % base.denominator;
            if (z > base.denominator / 2) {
                r++;
                z = base.denominator - z;
            }
            Fraction current = new Fraction(z, i * base.denominator);
            if (current.isLess(limit)) {
                limit = current;
                min_r = r;
                min_i = i;
            }
        }
        System.out.print(min_r);
        sc.close();
    }
}
